exercises.starter:
function countByNeighborhood(requests) {
  // tally requests into a {neighborhood: count} object
}

exercises.solution:
function countByNeighborhood(requests) {
  const counts = {}
  for (const r of requests) {
    counts[r.neighborhood] = (counts[r.neighborhood] || 0) + 1
  }
  return counts
}

