exercises.starter:
function avgDaysOpenByType(requests) {
  // map each type to its rounded average daysOpen
}

exercises.solution:
function avgDaysOpenByType(requests) {
  const sums = {}
  const counts = {}
  for (const r of requests) {
    sums[r.type] = (sums[r.type] || 0) + r.daysOpen
    counts[r.type] = (counts[r.type] || 0) + 1
  }
  const result = {}
  for (const t of Object.keys(sums)) {
    result[t] = Math.round(sums[t] / counts[t])
  }
  return result
}

exercises.starter:
function slowestNeighborhood(requests) {
  // return the neighborhood with the greatest average daysOpen
}

exercises.solution:
function slowestNeighborhood(requests) {
  const sums = {}
  const counts = {}
  for (const r of requests) {
    sums[r.neighborhood] = (sums[r.neighborhood] || 0) + r.daysOpen
    counts[r.neighborhood] = (counts[r.neighborhood] || 0) + 1
  }
  let best = null
  let bestAvg = -Infinity
  for (const nb of Object.keys(sums).sort()) {
    const avg = sums[nb] / counts[nb]
    if (avg > bestAvg) {
      bestAvg = avg
      best = nb
    }
  }
  return best
}

exercises.starter:
function busiestType(requests) {
  // return the most common request type
}

exercises.solution:
function busiestType(requests) {
  const counts = {}
  for (const r of requests) {
    counts[r.type] = (counts[r.type] || 0) + 1
  }
  let best = null
  let bestCount = 0
  for (const t of Object.keys(counts).sort()) {
    if (counts[t] > bestCount) {
      bestCount = counts[t]
      best = t
    }
  }
  return best
}
